import {enablePageScroll } from 'scroll-lock';

export function modalSuccessClose () {
  const modalSuccess = document.querySelector('.modal-success');
  const iconClose = modalSuccess.querySelector('.modal-success__btn')
  const btnClose = document.querySelector('.header__cross');

  iconClose.addEventListener('click', (e) => {
    if (e.currentTarget) {
      modalSuccess.classList.remove('active');
      enablePageScroll();
    }
  })
}