export function activeDots () {
  const dots = document.querySelectorAll('.gallery-dot__big');
  const items = document.querySelectorAll('.gallery__list-item');
  const galleries = document.querySelectorAll('.gallery');

  if (items.length > 0 && dots.length > 0) {
    dots.forEach((dot) => {
      dot.addEventListener('click', (e) => {
        if (window.innerWidth <= 1024) {
          items.forEach((item) => {
            item.classList.remove('active');
          })
          const element = dot.closest('.gallery__list-item');
          element.classList.add('active');
        }
      })
    })

    galleries.forEach((gallery) => {
      gallery.addEventListener('click', (e) => {
        if (window.innerWidth <= 1024) {
          if (e.target.tagName.toLowerCase() === 'img' ||
            e.target.closest('.gallery-navigation') ||
            e.target.closest('.gallery__btn')) {
            items.forEach((item) => {
              item.classList.remove('active');
            })
          }
        }
      })
    })
  }
}