export function screen6Accordion () {
  const btn = document.querySelector('.screen6__more')
  const container = document.querySelector('.screen6__grid-container')

  if (btn) {
    container.addEventListener('click', (e) => {
        if (e.target.closest('.screen6__more')) {
        container.classList.add('active')
        btn.classList.add('active');
      }
    })
  }
}