export function validationForm () {
  const modalSuccess = document.querySelector('.modal-success');
  const formsCall = document.querySelectorAll(".form-call");
  const modalForm = document.querySelector('.modal-form');
  const btnClose = document.querySelector('.header__cross');
  const btnCall = document.querySelector('.header__phone');

  function validateInput (input) {
    const error = input.closest('.form-call__group').querySelector('.form-call__error');
    const value = input.value.trim();
    let isValid = true;

    if (!value) {
      input.classList.add('error');
      error.classList.add('active');
      isValid = false
    } else if (input.type === "text" && value.length < 2){
       input.classList.add('error');
         error.textContent = "Два и более символов";
         error.classList.add('active');
         isValid = false;
    } else if (input.type === "tel") {
      const telPattern = /^(\+38)?0\d{9}$/;
      if (!telPattern.test(value)) {
        input.classList.add('error');
        error.textContent = "(0XX) XXX-XX-XX";
        error.classList.add('active');
        isValid = false;
      }  else {
        input.classList.remove('error');
        error.classList.remove('active');
      }
    } else {
      input.classList.remove('error');
      error.classList.remove('active');
    }
    return isValid;
  }

  formsCall.forEach(form => {
    const inputs = form.querySelectorAll("input");
    inputs.forEach(input => {
      if (input.type === "tel") {
        input.addEventListener("input", e => {
          e.target.value = e.target.value.replace(/[^0-9+\-\(\)\s]/g, '');
        });
      }
      input.addEventListener("blur", e => {
        validateInput(input);
      })

      input.addEventListener("input", e => {
        validateInput(input);
      })
    })

    form.addEventListener("submit", e => {
      e.preventDefault();
      let formValid = true;

      inputs.forEach(input => {
        if (!validateInput(input)) {
          formValid = false;
        }
      })

      if (formValid) {
        modalForm.classList.remove('active');
        btnClose.classList.remove('active');
        btnCall.classList.remove('off');
        modalSuccess.classList.add('active');

        inputs.forEach(input => {
          input.value ='';
          const error = input.closest('.form-call__group').querySelector('.form-call__error');
          input.classList.remove('error');
          error.classList.remove('active');
          error.textContent = "Заполните, пожалуйста, это поле.";
        })
      }
    })
  })
}
